// stats.js — 形状示例（自己敲）
function sum(xs) {
  let total = 0
  for (const n of xs) total += n
  return total
}
function max(xs) {
  let m = xs[0]
  for (const n of xs) if (n > m) m = n
  return m
}
const nums = [3, 1, 4, 1, 5]
console.log(sum(nums), max(nums))
